class Solution {
  private static boolean violates(int[] cnt, int v) {
    for (int a = 1; a < v; a++) {
      int b = v - a;
      if (a < b && cnt[a] > 0 && cnt[b] > 0) return true;
      if (a == b && cnt[a] >= 2) return true;
    }
    for (int a = 1; a + v <= 500; a++) if (cnt[a] > 0 && cnt[a + v] > 0) return true;
    return false;
  }

  public int maxSubarray(int[] nums) {
    int[] cnt = new int[501];
    int left = 0, best = 0;
    for (int r = 0; r < nums.length; r++) {
      while (violates(cnt, nums[r])) cnt[nums[left++]]--;
      cnt[nums[r]]++;
      best = Math.max(best, r - left + 1);
    }
    return best;
  }
}
